import numpy as np
def equation(t, P, params):
    H = P**2/(1+P**2)
    f = params[0] + params[1]*P + params[2]*P**2 + params[3]/P + params[4]/np.sqrt(P) + params[5]*H + params[6]*np.exp(-P)
    return f + params[7]*t*np.sqrt(P) + params[8]*np.cos(params[9]*P)

import numpy as np
def equation(t, P, params):
    n = params[7]; K = params[8]
    H = P**n/(K**n+P**n)
    f = params[0] + params[1]*P + params[2]*P**2 + params[3]/P + params[4]/np.sqrt(P) + params[5]*H
    return f + params[6]*t*np.sqrt(P) + params[9]*np.exp(-P)
